export const SETUP_SH_BODY = "# Floway agent setup installer (Bash 3.2+).\n#\n# Fixed, checked-in body. The Bash assignment prefix (the FLOWAY_*\n# variables and a trace-suppressing `set +x`) is prepended per request by the\n# gateway, so this file starts straight at the installer logic with no shebang.\n#\n# Claude Code and Codex are configured as independent transactional units: a\n# failure in one neither rolls back nor skips the other, and any selected-agent\n# failure makes the whole script exit non-zero. Errexit is deliberately NOT set\n# — Bash disables it inside the `if agent; then ... fi` guards used for that\n# independent aggregation, so control flow relies on explicit checks and\n# per-agent rollback instead.\n\nset -u\numask 077\nset -o pipefail 2>/dev/null || true\n\n# The API key remains a shell variable, not an exported process-environment\n# value. `export -n` also neutralizes an identically named exported variable\n# inherited from the caller. jq/awk receive it only on the individual\n# invocations that need it; the official installer and Claude CLI never inherit\n# it.\nexport -n FLOWAY_API_KEY 2>/dev/null || true\n\nFLOWAY_SETUP_TMPDIR=\"\"\n_cleanup() {\n  if [ -n \"$FLOWAY_SETUP_TMPDIR\" ]; then\n    rm -rf \"$FLOWAY_SETUP_TMPDIR\" 2>/dev/null || true\n  fi\n}\ntrap _cleanup EXIT INT TERM\n\n# Resolved lazily by ensure_jq: either `jq` on PATH or a verified pinned build.\nJQ=\"\"\n\n# Managed-key merge applied to the existing Claude settings document. Only the\n# keys Floway owns are touched; every unrelated key and env var is preserved.\n# An empty optional value means \"remove that managed key\". The API key is read\n# from the environment (`env.FLOWAY_API_KEY`) so it stays out of argv.\nCLAUDE_MERGE_PROGRAM='\n  if type != \"object\" then error(\"root is not a JSON object\")\n  elif (has(\"env\") and ((.env | type) != \"object\")) then error(\"env is not a JSON object\")\n  else . end\n  | (if (has(\"env\") | not) then .env = {} else . end)\n  | .env.ANTHROPIC_BASE_URL = $baseUrl\n  | .env.ANTHROPIC_AUTH_TOKEN = env.FLOWAY_API_KEY\n  | (if $model == \"\" then del(.env.ANTHROPIC_MODEL) else .env.ANTHROPIC_MODEL = $model end)\n  | (if $sonnet == \"\" then del(.env.ANTHROPIC_DEFAULT_SONNET_MODEL) else .env.ANTHROPIC_DEFAULT_SONNET_MODEL = $sonnet end)\n  | (if $haiku == \"\" then del(.env.ANTHROPIC_DEFAULT_HAIKU_MODEL) else .env.ANTHROPIC_DEFAULT_HAIKU_MODEL = $haiku end)\n  | (if $discovery == \"1\" then .env.CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY = \"1\" else del(.env.CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY) end)\n  | (if $effort == \"\" then del(.effortLevel) else .effortLevel = $effort end)\n'\n\n# --- common helpers ---------------------------------------------------------\n\n# Redact every literal occurrence of the API key from a text stream. The key is\n# read from the environment (never argv) and matched with index() so arbitrary\n# key characters are treated literally rather than as a regex.\nredact_key() {\n  FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" awk '\n    BEGIN { k = ENVIRON[\"FLOWAY_API_KEY\"]; kl = length(k) }\n    {\n      if (kl == 0) { print; next }\n      line = $0; out = \"\"\n      while ((p = index(line, k)) > 0) {\n        out = out substr(line, 1, p - 1) \"***\"\n        line = substr(line, p + kl)\n      }\n      print out line\n    }\n  '\n}\n\n# Print the SHA-256 of a file using whatever hashing tool is available; empty\n# output signals that none is.\n_sha256_of() {\n  if command -v sha256sum >/dev/null 2>&1; then\n    sha256sum \"$1\" | awk '{ print $1 }'\n  elif command -v shasum >/dev/null 2>&1; then\n    shasum -a 256 \"$1\" | awk '{ print $1 }'\n  elif command -v openssl >/dev/null 2>&1; then\n    openssl dgst -sha256 \"$1\" | awk '{ print $NF }'\n  fi\n}\n\n# Run a command under a wall-clock limit. macOS ships no `timeout`, so the\n# Bash-3.2 fallback enables job control for one launch, placing the command and\n# all ordinary descendants in a dedicated process group. The watchdog signals\n# that group with TERM then KILL, retains its process-group id across root exit,\n# and the parent waits for escalation to finish before returning 124.\n_run_with_timeout() {\n  _rwt_secs=$1\n  shift\n  if command -v timeout >/dev/null 2>&1; then\n    timeout \"$_rwt_secs\" \"$@\"\n    return $?\n  fi\n  if command -v gtimeout >/dev/null 2>&1; then\n    gtimeout \"$_rwt_secs\" \"$@\"\n    return $?\n  fi\n\n  _rwt_marker=$(mktemp \"$FLOWAY_SETUP_TMPDIR/timeout.XXXXXX\") || return 1\n  rm -f \"$_rwt_marker\"\n  if [ -n \"${FLOWAY_INSTALLER_TEST_TRACE_TIMEOUT:-}\" ]; then\n    printf 'Floway test: timeout fallback: process-tree\\n'\n  fi\n  set -m\n  \"$@\" &\n  _rwt_pid=$!\n  set +m\n  (\n    # The watchdog must not retain the installer's stdout/stderr descriptors\n    # after its parent shell is killed; otherwise a pipe consumer waits for the\n    # orphaned sleep to exit before receiving EOF.\n    exec </dev/null >/dev/null 2>&1\n    sleep \"$_rwt_secs\"\n    if kill -0 \"$_rwt_pid\" 2>/dev/null; then\n      : > \"$_rwt_marker\"\n      kill -TERM -- \"-$_rwt_pid\" 2>/dev/null || true\n      sleep 1\n      kill -KILL -- \"-$_rwt_pid\" 2>/dev/null || true\n    fi\n  ) &\n  _rwt_watchdog=$!\n  wait \"$_rwt_pid\"\n  _rwt_status=$?\n  if [ -e \"$_rwt_marker\" ]; then\n    # The timeout path waits through TERM→KILL escalation; the process-group id\n    # remains valid even after its original leader exits.\n    wait \"$_rwt_watchdog\" 2>/dev/null || true\n    rm -f \"$_rwt_marker\"\n    return 124\n  fi\n  kill \"$_rwt_watchdog\" 2>/dev/null || true\n  wait \"$_rwt_watchdog\" 2>/dev/null || true\n  rm -f \"$_rwt_marker\"\n  return $_rwt_status\n}\n\n# Download the pinned official jq build for this platform into the private\n# working directory and verify its hard-coded SHA-256 before use. Fails on an\n# unsupported platform, a download error, a missing hashing tool, or a checksum\n# mismatch — always before any configuration file is touched.\n_bootstrap_jq() {\n  _bj_os=$(uname -s)\n  _bj_arch=$(uname -m)\n  case \"$_bj_os\" in\n    Darwin) _bj_os_part=macos ;;\n    Linux) _bj_os_part=linux ;;\n    *) printf 'Floway: no pinned jq build for OS %s.\\n' \"$_bj_os\" >&2; return 1 ;;\n  esac\n  case \"$_bj_arch\" in\n    x86_64 | amd64) _bj_arch_part=amd64 ;;\n    arm64 | aarch64) _bj_arch_part=arm64 ;;\n    *) printf 'Floway: no pinned jq build for architecture %s.\\n' \"$_bj_arch\" >&2; return 1 ;;\n  esac\n  _bj_asset=\"jq-$_bj_os_part-$_bj_arch_part\"\n  # Pinned to jqlang/jq release jq-1.8.2. Each digest was verified against the\n  # release sha256sum.txt and the Sigstore build attestation\n  # (signer: jqlang/jq .github/workflows/ci.yml@refs/tags/jq-1.8.2).\n  # Ref: https://github.com/jqlang/jq/releases/tag/jq-1.8.2\n  case \"$_bj_asset\" in\n    jq-macos-amd64) _bj_sha=e94b266e3c26690550006abe63152b782280f4e14374accdf04cbde844f00bc0 ;;\n    jq-macos-arm64) _bj_sha=2d75340ba57a4b4b4c8708a21c2dc8e958a48aaa8bba13b27f77f6e4c0eca07e ;;\n    jq-linux-amd64) _bj_sha=b1c22172dd303f3be49e935aa56aa48a8b7a46e0bc838b4997d3bb451495870f ;;\n    jq-linux-arm64) _bj_sha=8b85c817833814ddca00a144c33705546355afccf0cf39b188f3cdb48b852309 ;;\n    *) return 1 ;;\n  esac\n  _bj_url=\"https://github.com/jqlang/jq/releases/download/jq-1.8.2/$_bj_asset\"\n  _bj_dest=\"$FLOWAY_SETUP_TMPDIR/$_bj_asset\"\n  printf 'Floway: jq not found on PATH; fetching the pinned jq-1.8.2 build...\\n'\n  if ! curl -fsSL --connect-timeout 10 --max-time 120 -o \"$_bj_dest\" \"$_bj_url\"; then\n    printf 'Floway: failed to download jq from %s\\n' \"$_bj_url\" >&2\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  _bj_actual=$(_sha256_of \"$_bj_dest\")\n  if [ -z \"$_bj_actual\" ]; then\n    printf 'Floway: no SHA-256 tool available to verify the jq download.\\n' >&2\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  if [ \"$_bj_actual\" != \"$_bj_sha\" ]; then\n    printf 'Floway: jq checksum mismatch; refusing to use the download.\\n' >&2\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  if ! chmod 700 \"$_bj_dest\"; then\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  JQ=\"$_bj_dest\"\n}\n\n# Resolve a usable jq: prefer PATH, else provision the pinned build. The\n# FLOWAY_INSTALLER_TEST_NO_JQ_DOWNLOAD hook lets the test harness assert the\n# fail-before-mutation path without reaching the network.\nensure_jq() {\n  if [ -n \"$JQ\" ]; then\n    return 0\n  fi\n  if command -v jq >/dev/null 2>&1; then\n    JQ=jq\n    return 0\n  fi\n  if [ -n \"${FLOWAY_INSTALLER_TEST_NO_JQ_DOWNLOAD:-}\" ]; then\n    return 1\n  fi\n  _bootstrap_jq\n}\n\n# Download an installer to the private working directory, refuse anything that\n# is not a shell script (region blocks and captive portals serve HTML in place\n# of the real installer), then execute it without sudo.\n_download_and_run_installer() {\n  _dri_url=$1\n  _dri_file=$(mktemp \"$FLOWAY_SETUP_TMPDIR/install.XXXXXX\") || return 1\n  if ! curl -fsSL --connect-timeout 10 --max-time 120 -o \"$_dri_file\" \"$_dri_url\"; then\n    printf 'Floway: could not download the installer from %s\\n' \"$_dri_url\" >&2\n    rm -f \"$_dri_file\"\n    return 1\n  fi\n  # Reject common HTML responses while allowing official shell content with or\n  # without a shebang (some installer CDNs prepend comments).\n  if awk '\n      NR <= 20 {\n        line = tolower($0)\n        if (line ~ /^[[:space:]]*(<!doctype[[:space:]]+html|<html([[:space:]>])|<head([[:space:]>])|<body([[:space:]>]))/) found = 1\n      }\n      END { exit found ? 0 : 1 }\n    ' \"$_dri_file\"; then\n    printf 'Floway: the installer download was HTML, not an executable script (a login or region-block page?).\\n' >&2\n    rm -f \"$_dri_file\"\n    return 1\n  fi\n  if ! awk 'NF { found = 1 } END { exit found ? 0 : 1 }' \"$_dri_file\"; then\n    printf 'Floway: the installer download was empty.\\n' >&2\n    rm -f \"$_dri_file\"\n    return 1\n  fi\n  _dri_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-120}\n  _run_with_timeout \"$_dri_timeout\" env -u FLOWAY_API_KEY bash \"$_dri_file\"\n  _dri_rc=$?\n  rm -f \"$_dri_file\"\n  return $_dri_rc\n}\n\n# --- Claude Code ------------------------------------------------------------\n\n# Resolve the Claude Code executable. The PATH winner is authoritative; known\n# official user-local locations are also consulted so an install that is not on\n# PATH is still found, and so multiple installations can be flagged.\n# Ref: https://docs.claude.com/en/docs/claude-code/troubleshoot-install\nclaude_discover() {\n  CLAUDE_BIN=\"\"\n  CLAUDE_INSTALL_COUNT=0\n  _cd_path=$(command -v claude 2>/dev/null || true)\n  if [ -n \"$_cd_path\" ]; then\n    CLAUDE_BIN=\"$_cd_path\"\n    CLAUDE_INSTALL_COUNT=1\n  fi\n  for _cd_cand in \\\n    \"$HOME/.local/bin/claude\" \\\n    \"$HOME/.claude/local/claude\" \\\n    \"$HOME/.bun/bin/claude\" \\\n    \"/opt/homebrew/bin/claude\" \\\n    \"/usr/local/bin/claude\"; do\n    [ -x \"$_cd_cand\" ] || continue\n    [ \"$_cd_cand\" = \"$_cd_path\" ] && continue\n    CLAUDE_INSTALL_COUNT=$((CLAUDE_INSTALL_COUNT + 1))\n    if [ -z \"$CLAUDE_BIN\" ]; then\n      CLAUDE_BIN=\"$_cd_cand\"\n    fi\n  done\n}\n\n# Install the official user-local Claude Code build. The\n# FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT hook — read from the ambient\n# environment, never emitted by the gateway — substitutes a fake installer\n# under test.\ninstall_claude() {\n  if [ -n \"${FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT:-}\" ]; then\n    _ic_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-120}\n    _run_with_timeout \"$_ic_timeout\" env -u FLOWAY_API_KEY bash \"$FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT\"\n    return $?\n  fi\n  # Ref: https://docs.claude.com/en/docs/claude-code/setup (\"Native Install\").\n  _download_and_run_installer \"${FLOWAY_INSTALLER_TEST_CLAUDE_URL:-https://claude.ai/install.sh}\"\n}\n\n# Ensure Claude Code is present, installing it only when absent. An existing\n# install is never upgraded or compatibility-checked.\nclaude_ensure_installed() {\n  claude_discover\n  if [ \"$CLAUDE_INSTALL_COUNT\" -gt 1 ]; then\n    printf 'Floway: multiple Claude Code installations detected; using %s.\\n' \"$CLAUDE_BIN\" >&2\n  fi\n  if [ \"$CLAUDE_INSTALL_COUNT\" -ge 1 ]; then\n    return 0\n  fi\n  printf 'Floway: Claude Code CLI not found; installing the official user-local build...\\n'\n  if ! install_claude; then\n    return 1\n  fi\n  hash -r 2>/dev/null || true\n  claude_discover\n  [ \"$CLAUDE_INSTALL_COUNT\" -ge 1 ]\n}\n\n# Restore the settings file to its pre-run state: replace it from the backup\n# when one exists, or remove the file entirely when this run created it.\nclaude_rollback_settings() {\n  if [ \"${CLAUDE_SETTINGS_EXISTED:-0}\" -eq 1 ]; then\n    if [ -n \"${CLAUDE_SETTINGS_BACKUP:-}\" ] && [ -e \"$CLAUDE_SETTINGS_BACKUP\" ]; then\n      mv \"$CLAUDE_SETTINGS_BACKUP\" \"$CLAUDE_SETTINGS_PATH\" 2>/dev/null || true\n    fi\n  else\n    rm -f \"$CLAUDE_SETTINGS_PATH\" 2>/dev/null || true\n  fi\n}\n\n# Surgically merge the managed keys into the Claude settings file: validate the\n# existing document, back it up, construct and validate the replacement in the\n# same directory, then atomically rename it into place at mode 0600.\nclaude_write_settings() {\n  _cw_dir=\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}\"\n  CLAUDE_SETTINGS_PATH=\"$_cw_dir/settings.json\"\n  CLAUDE_SETTINGS_BACKUP=\"\"\n  CLAUDE_SETTINGS_EXISTED=0\n\n  if ! mkdir -p \"$_cw_dir\"; then\n    printf 'Floway: could not create %s\\n' \"$_cw_dir\" >&2\n    return 1\n  fi\n\n  if [ -e \"$CLAUDE_SETTINGS_PATH\" ]; then\n    CLAUDE_SETTINGS_EXISTED=1\n    if ! \"$JQ\" '\n        if type != \"object\" then error(\"root is not a JSON object\")\n        elif (has(\"env\") and ((.env | type) != \"object\")) then error(\"env is not a JSON object\")\n        else . end\n      ' \"$CLAUDE_SETTINGS_PATH\" >/dev/null 2>&1; then\n      printf 'Floway: %s is not valid Claude settings; leaving it untouched.\\n' \"$CLAUDE_SETTINGS_PATH\" >&2\n      return 1\n    fi\n    _cw_base=$(cat \"$CLAUDE_SETTINGS_PATH\")\n    CLAUDE_SETTINGS_BACKUP=\"$CLAUDE_SETTINGS_PATH.floway-backup.$(date +%Y%m%d%H%M%S).$$\"\n    if ! cp \"$CLAUDE_SETTINGS_PATH\" \"$CLAUDE_SETTINGS_BACKUP\"; then\n      printf 'Floway: could not back up %s\\n' \"$CLAUDE_SETTINGS_PATH\" >&2\n      return 1\n    fi\n  else\n    _cw_base='{}'\n  fi\n\n  _cw_stage=\"$CLAUDE_SETTINGS_PATH.floway-stage.$$\"\n  if ! printf '%s' \"$_cw_base\" | FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" \"$JQ\" \\\n      --arg baseUrl \"$FLOWAY_BASE_URL\" \\\n      --arg model \"$FLOWAY_CLAUDE_MODEL\" \\\n      --arg sonnet \"$FLOWAY_CLAUDE_DEFAULT_SONNET_MODEL\" \\\n      --arg haiku \"$FLOWAY_CLAUDE_DEFAULT_HAIKU_MODEL\" \\\n      --arg discovery \"$FLOWAY_CLAUDE_MODEL_DISCOVERY\" \\\n      --arg effort \"$FLOWAY_CLAUDE_EFFORT_LEVEL\" \\\n      \"$CLAUDE_MERGE_PROGRAM\" > \"$_cw_stage\"; then\n    printf 'Floway: failed to construct updated Claude settings.\\n' >&2\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n\n  if ! FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" \"$JQ\" -e --arg baseUrl \"$FLOWAY_BASE_URL\" '\n      (type == \"object\")\n      and ((.env | type) == \"object\")\n      and (.env.ANTHROPIC_BASE_URL == $baseUrl)\n      and (.env.ANTHROPIC_AUTH_TOKEN == env.FLOWAY_API_KEY)\n    ' \"$_cw_stage\" >/dev/null 2>&1; then\n    printf 'Floway: staged Claude settings failed validation.\\n' >&2\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n\n  if ! chmod 600 \"$_cw_stage\"; then\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n\n  if ! mv \"$_cw_stage\" \"$CLAUDE_SETTINGS_PATH\"; then\n    printf 'Floway: could not replace %s\\n' \"$CLAUDE_SETTINGS_PATH\" >&2\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n}\n\n# Confirm the gateway's authenticated model directory answers. No inference\n# request is issued. The key is passed through a mode-0600 curl config file so\n# it never reaches the process argument list.\nclaude_check_models() {\n  _cm_cfg=\"$FLOWAY_SETUP_TMPDIR/claude-curl.cfg\"\n  {\n    printf 'silent\\n'\n    printf 'show-error\\n'\n    printf 'fail\\n'\n    printf 'header = \"anthropic-version: 2023-06-01\"\\n'\n    printf 'header = \"Authorization: Bearer %s\"\\n' \"$FLOWAY_API_KEY\"\n    printf 'header = \"x-api-key: %s\"\\n' \"$FLOWAY_API_KEY\"\n  } > \"$_cm_cfg\"\n  chmod 600 \"$_cm_cfg\" 2>/dev/null || true\n  curl -K \"$_cm_cfg\" --connect-timeout 10 --max-time 30 -o /dev/null \"${FLOWAY_BASE_URL%/}/v1/models\"\n  _cm_rc=$?\n  rm -f \"$_cm_cfg\"\n  return $_cm_rc\n}\n\n# Verify the Claude configuration without inference: reparse the written\n# settings, print the raw CLI version, reach the authenticated model directory,\n# and run `claude doctor` when the subcommand exists. Doctor output is redacted\n# before it is surfaced.\nclaude_verify() {\n  if ! FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" \"$JQ\" -e --arg baseUrl \"$FLOWAY_BASE_URL\" '\n      (type == \"object\")\n      and ((.env | type) == \"object\")\n      and (.env.ANTHROPIC_BASE_URL == $baseUrl)\n      and (.env.ANTHROPIC_AUTH_TOKEN == env.FLOWAY_API_KEY)\n    ' \"$CLAUDE_SETTINGS_PATH\" >/dev/null 2>&1; then\n    printf 'Floway: the written Claude settings did not reparse as expected.\\n' >&2\n    return 1\n  fi\n\n  _cv_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-30}\n  _cv_version_file=\"$FLOWAY_SETUP_TMPDIR/claude-version.out\"\n  if _run_with_timeout \"$_cv_timeout\" \"$CLAUDE_BIN\" --version > \"$_cv_version_file\" 2>&1; then\n    _cv_version=$(cat \"$_cv_version_file\")\n  else\n    _cv_version_status=$?\n    if [ \"$_cv_version_status\" -eq 124 ]; then\n      printf 'Floway: `claude --version` timed out.\\n' >&2\n    else\n      printf 'Floway: `claude --version` failed.\\n' >&2\n    fi\n    return 1\n  fi\n  printf 'Floway: Claude Code version: %s\\n' \"$_cv_version\"\n\n  if ! claude_check_models; then\n    printf 'Floway: could not reach the authenticated model directory at %s/v1/models\\n' \"${FLOWAY_BASE_URL%/}\" >&2\n    return 1\n  fi\n  printf 'Floway: reached the authenticated model directory (no inference issued).\\n'\n\n  _cv_doctor_help=\"$FLOWAY_SETUP_TMPDIR/claude-doctor-help.out\"\n  if _run_with_timeout \"$_cv_timeout\" \"$CLAUDE_BIN\" doctor --help </dev/null > \"$_cv_doctor_help\" 2>&1; then\n    if _run_with_timeout \"$_cv_timeout\" \"$CLAUDE_BIN\" doctor </dev/null > \"$FLOWAY_SETUP_TMPDIR/claude-doctor.out\" 2>&1; then\n      printf 'Floway: claude doctor reported no blocking issues.\\n'\n    else\n      _cv_doctor_status=$?\n      if [ \"$_cv_doctor_status\" -eq 124 ]; then\n        printf 'Floway: claude doctor timed out.\\n' >&2\n      else\n        printf 'Floway: claude doctor reported a problem:\\n' >&2\n        redact_key < \"$FLOWAY_SETUP_TMPDIR/claude-doctor.out\" >&2\n      fi\n      return 1\n    fi\n  else\n    _cv_help_status=$?\n    if [ \"$_cv_help_status\" -eq 124 ]; then\n      printf 'Floway: claude doctor capability check timed out.\\n' >&2\n      return 1\n    fi\n    if grep -Eiq '(unknown|unrecognized|invalid|no such).*(command|subcommand).*doctor|doctor.*(unknown|unrecognized|invalid).*(command|subcommand)' \"$_cv_doctor_help\"; then\n      printf 'Floway: this Claude Code build has no doctor command; skipping that check.\\n'\n    else\n      printf 'Floway: claude doctor capability check failed.\\n' >&2\n      redact_key < \"$_cv_doctor_help\" >&2\n      return 1\n    fi\n  fi\n}\n\n# Configure Claude Code as one transactional unit. jq must resolve before any\n# mutation. Verification failure rolls back the settings write; a freshly\n# installed CLI is never uninstalled.\nconfigure_claude() {\n  printf 'Floway: configuring Claude Code...\\n'\n  if ! ensure_jq; then\n    printf 'Floway: jq is required to configure Claude Code but is unavailable and could not be provisioned for this platform. Install jq and re-run.\\n' >&2\n    return 1\n  fi\n  if ! claude_ensure_installed; then\n    printf 'Floway: Claude Code CLI is unavailable and could not be installed.\\n' >&2\n    return 1\n  fi\n  if ! claude_write_settings; then\n    return 1\n  fi\n  if ! claude_verify; then\n    printf 'Floway: Claude Code verification failed; rolling back settings.\\n' >&2\n    claude_rollback_settings\n    return 1\n  fi\n  printf 'Floway: Claude Code configured.\\n'\n}\n\n# --- Codex ------------------------------------------------------------------\n\n# Codex configuration is implemented in the next task. Reporting failure keeps a\n# selected-but-unconfigured Codex from being summarized as done.\nconfigure_codex() {\n  printf 'Floway: Codex configuration is not implemented in this build yet.\\n' >&2\n  return 1\n}\n\n# --- run --------------------------------------------------------------------\n\nFLOWAY_SETUP_TMPDIR=$(mktemp -d \"${TMPDIR:-/tmp}/floway-setup.XXXXXX\") || {\n  printf 'Floway: could not create a private working directory.\\n' >&2\n  exit 1\n}\nchmod 700 \"$FLOWAY_SETUP_TMPDIR\" 2>/dev/null || true\n\nCLAUDE_RESULT=skipped\nCODEX_RESULT=skipped\nOVERALL=0\n\nif [ -n \"$FLOWAY_INSTALL_CLAUDE\" ]; then\n  if configure_claude; then\n    CLAUDE_RESULT=configured\n  else\n    CLAUDE_RESULT=failed\n    OVERALL=1\n  fi\nfi\n\nif [ -n \"$FLOWAY_INSTALL_CODEX\" ]; then\n  if configure_codex; then\n    CODEX_RESULT=configured\n  else\n    CODEX_RESULT=failed\n    OVERALL=1\n  fi\nfi\n\nprintf '\\nFloway agent setup summary:\\n'\nprintf '  Claude Code: %s\\n' \"$CLAUDE_RESULT\"\nprintf '  Codex:       %s\\n' \"$CODEX_RESULT\"\n\nexit \"$OVERALL\"\n";

export const SETUP_PS1_BODY = "# Floway agent setup installer (PowerShell).\n#\n# Fixed, checked-in body. The language-native assignment prefix (the $Floway*\n# variables and a trace-suppressing `Set-PSDebug -Off`) is prepended per\n# request by the gateway, so this file starts straight at the installer logic.\n#\n# Claude Code and Codex are configured as independent transactional units: a\n# failure in one neither rolls back nor skips the other, and any selected-agent\n# failure makes the whole script exit non-zero. Each agent runs inside its own\n# try/catch so a terminating error is contained and rolled back rather than\n# aborting the other agent.\n\n$ErrorActionPreference = 'Stop'\n# Keep native (non-cmdlet) command failures from auto-throwing on PowerShell\n# 7.3+, so explicit $LASTEXITCODE checks stay authoritative across versions.\n$PSNativeCommandUseErrorActionPreference = $false\n\n# The server prefix uses ordinary variables, but defensively remove identically\n# named ambient environment variables so installers and CLI subprocesses cannot\n# inherit the API key.\nRemove-Item Env:FLOWAY_API_KEY -ErrorAction SilentlyContinue\nRemove-Item Env:FlowayApiKey -ErrorAction SilentlyContinue\n\n# --- common helpers ---------------------------------------------------------\n\nfunction Set-FlowayProp {\n  param($Target, [string]$Name, $Value)\n  if ($Target.PSObject.Properties.Name -contains $Name) { $Target.$Name = $Value }\n  else { $Target | Add-Member -NotePropertyName $Name -NotePropertyValue $Value }\n}\n\nfunction Remove-FlowayProp {\n  param($Target, [string]$Name)\n  if ($Target.PSObject.Properties.Name -contains $Name) { $Target.PSObject.Properties.Remove($Name) }\n}\n\n# A null optional value means \"remove this managed key\"; any other value is set.\nfunction Set-FlowayOptionalProp {\n  param($Target, [string]$Name, $Value)\n  if ($null -eq $Value) { Remove-FlowayProp $Target $Name } else { Set-FlowayProp $Target $Name $Value }\n}\n\n# Redact every occurrence of the API key from text before it is surfaced.\nfunction Protect-FlowaySecret {\n  param([string]$Text)\n  return ($Text -replace [regex]::Escape($FlowayApiKey), '***')\n}\n\n# Restrict a file to the current user: chmod 0600 on Unix, an inheritance-free\n# owner-only ACL on Windows.\nfunction Protect-FlowayFile {\n  param([string]$Path)\n  if (($PSVersionTable.PSVersion.Major -ge 6) -and (-not $IsWindows)) {\n    & chmod 600 $Path\n    if ($LASTEXITCODE -ne 0) { throw \"could not restrict $Path to mode 0600.\" }\n    return\n  }\n  $acl = New-Object System.Security.AccessControl.FileSecurity\n  $identity = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name\n  $rule = New-Object System.Security.AccessControl.FileSystemAccessRule($identity, 'FullControl', 'Allow')\n  $acl.SetAccessRuleProtection($true, $false)\n  $acl.AddAccessRule($rule)\n  Set-Acl -Path $Path -AclObject $acl\n}\n\n# Terminate a process and its descendants. PowerShell 7's runtime exposes the\n# tree-aware Kill(bool) overload; Windows PowerShell 5.1 uses taskkill /T.\nfunction Stop-FlowayProcessTree {\n  param([System.Diagnostics.Process]$Process)\n  $runningOnWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows\n  if ($runningOnWindows) {\n    & taskkill.exe /PID $Process.Id /T /F *> $null\n    if ($LASTEXITCODE -ne 0 -and (-not $Process.HasExited)) {\n      throw \"taskkill could not terminate process tree $($Process.Id).\"\n    }\n    return\n  }\n  try {\n    # .NET used by PowerShell 7 supports tree-aware termination on Unix.\n    $Process.Kill($true)\n  } catch {\n    if (-not $Process.HasExited) { throw \"could not terminate process tree $($Process.Id).\" }\n  }\n}\n\n# Execute a downloaded PowerShell installer in a fresh interpreter. The script\n# travels through stdin, while the API key exists only as a variable in this\n# parent process and its identically named environment variables were removed.\n# The official installer therefore cannot read the credential.\nfunction Invoke-FlowayPowerShellBody {\n  param([string]$Body, [int]$TimeoutSeconds)\n  $startInfo = New-Object System.Diagnostics.ProcessStartInfo\n  $startInfo.FileName = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName\n  $startInfo.Arguments = '-NoProfile -NonInteractive -Command -'\n  $startInfo.UseShellExecute = $false\n  $startInfo.CreateNoWindow = $true\n  $startInfo.RedirectStandardInput = $true\n  $startInfo.RedirectStandardOutput = $true\n  $startInfo.RedirectStandardError = $true\n  $process = New-Object System.Diagnostics.Process\n  $process.StartInfo = $startInfo\n  if (-not $process.Start()) { throw \"failed to start the installer interpreter.\" }\n  $stdoutTask = $process.StandardOutput.ReadToEndAsync()\n  $stderrTask = $process.StandardError.ReadToEndAsync()\n  $process.StandardInput.Write($Body)\n  $process.StandardInput.WriteLine()\n  $process.StandardInput.Close()\n  if (-not $process.WaitForExit($TimeoutSeconds * 1000)) {\n    Stop-FlowayProcessTree $process\n    $process.WaitForExit()\n    throw \"the installer timed out after $TimeoutSeconds seconds.\"\n  }\n  $stdout = $stdoutTask.GetAwaiter().GetResult()\n  $stderr = $stderrTask.GetAwaiter().GetResult()\n  if ($stdout) { Write-Host $stdout.TrimEnd() }\n  if ($stderr) { Write-Host $stderr.TrimEnd() }\n  if ($process.ExitCode -ne 0) { throw \"the installer exited with status $($process.ExitCode).\" }\n}\n\n# Download an installer, refuse anything that is not a script (region blocks and\n# captive portals serve HTML in place of the installer), then run it.\nfunction Invoke-FlowayRemoteInstaller {\n  param([string]$Uri)\n  $response = Invoke-WebRequest -Uri $Uri -UseBasicParsing -TimeoutSec 60\n  $body = [string]$response.Content\n  $contentType = [string]$response.Headers['Content-Type']\n  $looksLikeHtml = $contentType -match '(?i)^text/html(?:;|$)' -or $body -match '(?is)^\\s*(?:<!doctype\\s+html|<html(?:\\s|>))'\n  if ([string]::IsNullOrWhiteSpace($body) -or $looksLikeHtml) {\n    throw \"the installer download was HTML or empty, not an executable script (a login or region-block page?).\"\n  }\n  $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 120 }\n  Invoke-FlowayPowerShellBody -Body $body -TimeoutSeconds $timeoutSeconds\n}\n\n# --- Claude Code ------------------------------------------------------------\n\n# Resolve the Claude Code executable. The PATH winner is authoritative; known\n# official user-local locations are also consulted so an install that is not on\n# PATH is still found, and so multiple installations can be flagged.\n# Ref: https://docs.claude.com/en/docs/claude-code/troubleshoot-install\nfunction Get-FlowayClaudeExe {\n  $found = New-Object System.Collections.Generic.List[string]\n  $command = Get-Command claude -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1\n  if ($command) { $found.Add($command.Source) }\n  $candidates = @(\n    (Join-Path $HOME '.local/bin/claude'),\n    (Join-Path $HOME '.local/bin/claude.exe'),\n    (Join-Path $HOME '.claude/local/claude')\n  )\n  if ($env:USERPROFILE) { $candidates += (Join-Path $env:USERPROFILE '.local\\bin\\claude.exe') }\n  foreach ($candidate in $candidates) {\n    if ((Test-Path -LiteralPath $candidate) -and (-not $found.Contains($candidate))) { $found.Add($candidate) }\n  }\n  if ($found.Count -eq 0) { return $null }\n  if ($found.Count -gt 1) { Write-Host \"Floway: multiple Claude Code installations detected; using $($found[0]).\" }\n  return $found[0]\n}\n\n# Install the official user-local Claude Code build. The\n# FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT hook — read from the ambient\n# environment, never emitted by the gateway — substitutes a fake installer\n# under test.\nfunction Install-FlowayClaude {\n  if ($env:FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT) {\n    $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 120 }\n    $installer = Invoke-FlowayProcess -Exe $env:FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT -Arguments @() -TimeoutSeconds $timeoutSeconds\n    if ($installer.ExitCode -ne 0) { throw \"the test installer hook failed.\" }\n    return\n  }\n  # Ref: https://docs.claude.com/en/docs/claude-code/setup (\"Native Install\").\n  $installerUri = if ($env:FLOWAY_INSTALLER_TEST_CLAUDE_URL) { $env:FLOWAY_INSTALLER_TEST_CLAUDE_URL } else { 'https://claude.ai/install.ps1' }\n  Invoke-FlowayRemoteInstaller -Uri $installerUri\n}\n\n# Restore the settings file to its pre-run state: replace it from the backup\n# when one exists, or remove the file entirely when this run created it.\nfunction Restore-FlowayClaudeSettings {\n  if ($script:ClaudeSettingsExisted) {\n    if ($script:ClaudeSettingsBackup -and (Test-Path -LiteralPath $script:ClaudeSettingsBackup)) {\n      Move-Item -LiteralPath $script:ClaudeSettingsBackup -Destination $script:ClaudeSettingsPath -Force\n      Protect-FlowayFile $script:ClaudeSettingsPath\n    }\n  } elseif (Test-Path -LiteralPath $script:ClaudeSettingsPath) {\n    Remove-Item -LiteralPath $script:ClaudeSettingsPath -Force\n  }\n}\n\n# Surgically merge the managed keys into the Claude settings file: validate the\n# existing document, back it up, construct and validate the replacement in the\n# same directory, then atomically rename it into place with owner-only access.\nfunction Write-FlowayClaudeSettings {\n  $configDir = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $HOME '.claude' }\n  $script:ClaudeSettingsPath = Join-Path $configDir 'settings.json'\n  $script:ClaudeSettingsBackup = $null\n  $script:ClaudeSettingsExisted = $false\n  if (-not (Test-Path -LiteralPath $configDir)) {\n    New-Item -ItemType Directory -Path $configDir -Force | Out-Null\n  }\n\n  $document = $null\n  if (Test-Path -LiteralPath $script:ClaudeSettingsPath) {\n    $script:ClaudeSettingsExisted = $true\n    $raw = Get-Content -Raw -LiteralPath $script:ClaudeSettingsPath\n    try { $document = $raw | ConvertFrom-Json } catch { throw \"$($script:ClaudeSettingsPath) is not valid JSON; leaving it untouched.\" }\n    if ($document -isnot [System.Management.Automation.PSCustomObject]) { throw \"existing Claude settings root is not a JSON object.\" }\n    if (($document.PSObject.Properties.Name -contains 'env') -and ($document.env -isnot [System.Management.Automation.PSCustomObject])) {\n      throw \"existing Claude settings env is not a JSON object.\"\n    }\n    # DateTimeOffset.ToUnixTimeMilliseconds is unavailable on the .NET\n    # Framework version bundled with the Windows PowerShell 5.1 baseline.\n    $stamp = [long]([DateTimeOffset]::UtcNow - [DateTimeOffset]'1970-01-01T00:00:00Z').TotalMilliseconds\n    $script:ClaudeSettingsBackup = \"$($script:ClaudeSettingsPath).floway-backup.$stamp.$PID\"\n    try {\n      Copy-Item -LiteralPath $script:ClaudeSettingsPath -Destination $script:ClaudeSettingsBackup\n      Protect-FlowayFile $script:ClaudeSettingsBackup\n    } catch {\n      if (Test-Path -LiteralPath $script:ClaudeSettingsBackup) {\n        Remove-Item -LiteralPath $script:ClaudeSettingsBackup -Force\n      }\n      $script:ClaudeSettingsBackup = $null\n      throw\n    }\n  } else {\n    $document = [PSCustomObject]@{}\n  }\n\n  if ($document.PSObject.Properties.Name -notcontains 'env') {\n    $document | Add-Member -NotePropertyName env -NotePropertyValue ([PSCustomObject]@{})\n  }\n  Set-FlowayProp $document.env 'ANTHROPIC_BASE_URL' $FlowayBaseUrl\n  Set-FlowayProp $document.env 'ANTHROPIC_AUTH_TOKEN' $FlowayApiKey\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_MODEL' $FlowayClaudeModel\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_DEFAULT_SONNET_MODEL' $FlowayClaudeDefaultSonnetModel\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_DEFAULT_HAIKU_MODEL' $FlowayClaudeDefaultHaikuModel\n  if ($FlowayClaudeModelDiscovery) { Set-FlowayProp $document.env 'CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY' '1' }\n  else { Remove-FlowayProp $document.env 'CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY' }\n  Set-FlowayOptionalProp $document 'effortLevel' $FlowayClaudeEffortLevel\n\n  $stage = \"$($script:ClaudeSettingsPath).floway-stage.$PID\"\n  try {\n    # The stage exists and is owner-only before any secret JSON is written.\n    [System.IO.File]::Create($stage).Dispose()\n    Protect-FlowayFile $stage\n    $json = $document | ConvertTo-Json -Depth 100\n    # Write UTF-8 without a BOM on every PowerShell version so downstream JSON\n    # parsers accept the file.\n    [System.IO.File]::WriteAllText($stage, $json, (New-Object System.Text.UTF8Encoding($false)))\n    $check = Get-Content -Raw -LiteralPath $stage | ConvertFrom-Json\n    if (($check.env.ANTHROPIC_BASE_URL -ne $FlowayBaseUrl) -or ($check.env.ANTHROPIC_AUTH_TOKEN -ne $FlowayApiKey)) {\n      throw \"staged Claude settings failed validation.\"\n    }\n    # Windows PowerShell 5.1 only runs on Windows and has no $IsWindows\n    # automatic variable; PowerShell 6+ exposes it on every platform.\n    $runningOnWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows\n    if ($script:ClaudeSettingsExisted -and $runningOnWindows) {\n      # File.Replace preserves the destination ACL, so tighten it first rather\n      # than letting a permissive historical DACL survive the atomic replace.\n      Protect-FlowayFile $script:ClaudeSettingsPath\n      [System.IO.File]::Replace($stage, $script:ClaudeSettingsPath, $null)\n    } else {\n      # Move-Item is an atomic same-filesystem rename on Unix and creates a new\n      # target on Windows. Windows replacing an existing target uses File.Replace.\n      Move-Item -LiteralPath $stage -Destination $script:ClaudeSettingsPath -Force\n    }\n  } catch {\n    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Force }\n    Restore-FlowayClaudeSettings\n    throw\n  }\n}\n\n# Confirm the gateway's authenticated model directory answers. No inference\n# request is issued. The key travels in an in-process header table, never in a\n# process argument list.\nfunction Invoke-FlowayProcess {\n  param([string]$Exe, [string[]]$Arguments, [int]$TimeoutSeconds)\n  $startInfo = New-Object System.Diagnostics.ProcessStartInfo\n  $startInfo.FileName = $Exe\n  $startInfo.UseShellExecute = $false\n  $startInfo.CreateNoWindow = $true\n  $startInfo.RedirectStandardOutput = $true\n  $startInfo.RedirectStandardError = $true\n  # ArgumentList is unavailable in Windows PowerShell 5.1. These arguments are\n  # fixed internal tokens, so quoting them with ProcessStartInfo.Arguments is\n  # safe and keeps external input out of the child command line.\n  $startInfo.Arguments = ($Arguments | ForEach-Object { '\"' + $_.Replace('\"', '\\\"') + '\"' }) -join ' '\n  $process = New-Object System.Diagnostics.Process\n  $process.StartInfo = $startInfo\n  if (-not $process.Start()) { throw \"failed to start $Exe.\" }\n  $stdoutTask = $process.StandardOutput.ReadToEndAsync()\n  $stderrTask = $process.StandardError.ReadToEndAsync()\n  if (-not $process.WaitForExit($TimeoutSeconds * 1000)) {\n    Stop-FlowayProcessTree $process\n    $process.WaitForExit()\n    throw \"$Exe timed out after $TimeoutSeconds seconds.\"\n  }\n  $stdout = $stdoutTask.GetAwaiter().GetResult()\n  $stderr = $stderrTask.GetAwaiter().GetResult()\n  [PSCustomObject]@{ ExitCode = $process.ExitCode; Output = ($stdout + $stderr) }\n}\n\nfunction Test-FlowayModelDirectory {\n  $headers = @{\n    'Authorization'     = \"Bearer $FlowayApiKey\"\n    'x-api-key'         = $FlowayApiKey\n    'anthropic-version' = '2023-06-01'\n  }\n  $uri = ($FlowayBaseUrl.TrimEnd('/')) + '/v1/models'\n  try {\n    Invoke-WebRequest -Uri $uri -Headers $headers -Method Get -UseBasicParsing -TimeoutSec 30 | Out-Null\n    return $true\n  } catch {\n    return $false\n  }\n}\n\n# Verify the Claude configuration without inference: reparse the written\n# settings, print the raw CLI version, reach the authenticated model directory,\n# and run `claude doctor` when the subcommand exists. Doctor output is redacted\n# before it is surfaced.\nfunction Invoke-FlowayClaudeVerify {\n  param([string]$Exe)\n  $document = Get-Content -Raw -LiteralPath $script:ClaudeSettingsPath | ConvertFrom-Json\n  if (($document.env.ANTHROPIC_BASE_URL -ne $FlowayBaseUrl) -or ($document.env.ANTHROPIC_AUTH_TOKEN -ne $FlowayApiKey)) {\n    throw \"the written Claude settings did not reparse as expected.\"\n  }\n\n  $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 30 }\n  $version = Invoke-FlowayProcess -Exe $Exe -Arguments @('--version') -TimeoutSeconds $timeoutSeconds\n  if ($version.ExitCode -ne 0) { throw \"``claude --version`` failed.\" }\n  Write-Host \"Floway: Claude Code version: $($version.Output.Trim())\"\n\n  if (-not (Test-FlowayModelDirectory)) {\n    throw \"could not reach the authenticated model directory at $($FlowayBaseUrl.TrimEnd('/'))/v1/models\"\n  }\n  Write-Host \"Floway: reached the authenticated model directory (no inference issued).\"\n\n  $doctorHelp = Invoke-FlowayProcess -Exe $Exe -Arguments @('doctor', '--help') -TimeoutSeconds $timeoutSeconds\n  if ($doctorHelp.ExitCode -eq 0) {\n    $doctor = Invoke-FlowayProcess -Exe $Exe -Arguments @('doctor') -TimeoutSeconds $timeoutSeconds\n    if ($doctor.ExitCode -ne 0) {\n      Write-Host \"Floway: claude doctor reported a problem:`n$(Protect-FlowaySecret $doctor.Output)\"\n      throw \"claude doctor reported a problem.\"\n    }\n    Write-Host \"Floway: claude doctor reported no blocking issues.\"\n  } elseif ($doctorHelp.Output -match '(?i)(unknown|unrecognized|invalid|no such).*(command|subcommand).*doctor|doctor.*(unknown|unrecognized|invalid).*(command|subcommand)') {\n    Write-Host \"Floway: this Claude Code build has no doctor command; skipping that check.\"\n  } else {\n    Write-Host \"Floway: claude doctor capability check failed:`n$(Protect-FlowaySecret $doctorHelp.Output)\"\n    throw \"claude doctor capability check failed.\"\n  }\n}\n\n# Configure Claude Code as one transactional unit. Verification failure rolls\n# back the settings write; a freshly installed CLI is never uninstalled.\nfunction Set-FlowayClaude {\n  Write-Host \"Floway: configuring Claude Code...\"\n  $exe = Get-FlowayClaudeExe\n  if (-not $exe) {\n    Write-Host \"Floway: Claude Code CLI not found; installing the official user-local build...\"\n    Install-FlowayClaude\n    $exe = Get-FlowayClaudeExe\n    if (-not $exe) { throw \"Claude Code CLI is unavailable and could not be installed.\" }\n  }\n  Write-FlowayClaudeSettings\n  try {\n    Invoke-FlowayClaudeVerify $exe\n  } catch {\n    Write-Host \"Floway: Claude Code verification failed; rolling back settings.\"\n    Restore-FlowayClaudeSettings\n    throw\n  }\n  Write-Host \"Floway: Claude Code configured.\"\n}\n\n# --- Codex ------------------------------------------------------------------\n\n# Codex configuration is implemented in the next task. Throwing keeps a\n# selected-but-unconfigured Codex from being summarized as done.\nfunction Set-FlowayCodex {\n  throw \"Codex configuration is not implemented in this build yet.\"\n}\n\n# --- run --------------------------------------------------------------------\n\n$script:ClaudeResult = 'skipped'\n$script:CodexResult = 'skipped'\n$overall = 0\n\nif ($FlowayInstallClaude) {\n  try {\n    Set-FlowayClaude\n    $script:ClaudeResult = 'configured'\n  } catch {\n    Write-Host \"Floway: Claude Code setup failed: $(Protect-FlowaySecret ([string]$_.Exception.Message))\"\n    $script:ClaudeResult = 'failed'\n    $overall = 1\n  }\n}\n\nif ($FlowayInstallCodex) {\n  try {\n    Set-FlowayCodex\n    $script:CodexResult = 'configured'\n  } catch {\n    Write-Host \"Floway: Codex setup failed: $(Protect-FlowaySecret ([string]$_.Exception.Message))\"\n    $script:CodexResult = 'failed'\n    $overall = 1\n  }\n}\n\nWrite-Host \"\"\nWrite-Host \"Floway agent setup summary:\"\nWrite-Host \"  Claude Code: $($script:ClaudeResult)\"\nWrite-Host \"  Codex:       $($script:CodexResult)\"\n\nexit $overall\n";
